 p_id=>1
,p_name=>'Home'
,p_alias=>'HOME'
,p_step_title=>'SEGUROS'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.broker-home {',
'    max-width: 1200px;',
'    margin: 0 auto;',
'    padding: 24px 12px 40px;',
'}',
'',
'.broker-home__hero {',
'    position: relative;',
'    overflow: hidden;',
'    display: flex;',
'    align-items: center;',
'    justify-content: space-between;',
'    min-height: 270px;',
'    padding: 48px;',
'    border-radius: 28px;',
'    background:',
'        radial-gradient(',
'            circle at top right,',
'            rgba(255, 255, 255, 0.22),',
'            transparent 35%',
'        ),',
'        linear-gradient(135deg, #172554 0%, #1d4ed8 100%);',
'    box-shadow: 0 20px 50px rgba(15, 23, 42, 0.16);',
'}',
'',
'.broker-home__content {',
'    position: relative;',
'    z-index: 2;',
'    max-width: 650px;',
'}',
'',
'.broker-home__badge {',
'    display: inline-block;',
'    margin-bottom: 18px;',
'    padding: 7px 14px;',
'    border: 1px solid rgba(255, 255, 255, 0.22);',
'    border-radius: 999px;',
'    background: rgba(255, 255, 255, 0.12);',
'    color: #ffffff;',
'    font-size: 12px;',
'    font-weight: 600;',
'    letter-spacing: 0.08em;',
'    text-transform: uppercase;',
'}',
'',
'.broker-home__hero h1 {',
'    margin: 0 0 16px;',
'    color: #ffffff;',
'    font-size: clamp(32px, 5vw, 52px);',
'    font-weight: 750;',
'    line-height: 1.08;',
'}',
'',
'.broker-home__hero p {',
'    max-width: 580px;',
