'           :P1_LAST_NAME',
'    FROM   apex_workspace_apex_users',
'    WHERE  UPPER(user_name) = UPPER(:APP_USER);',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P1_FIRST_NAME := :APP_USER;',
'        :P1_LAST_NAME  := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13412016663978710
);
