,p_chart_id=>wwv_flow_imp.id(36998893178546597)
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
unistr('    ''P\00F3lizas'' AS nombre_serie,'),
'    CASE',
'        WHEN UPPER(TRIM(p.renewal_type)) = ''NUEVA''',
'            THEN ''Nuevas''',
'        WHEN UPPER(TRIM(p.renewal_type)) IN (''RENOVADA'')',
'            THEN ''Renovadas''',
'        ELSE ''Sin clasificar''',
'    END AS etiqueta,',
'    COUNT(*) AS valor',
'FROM policies p',
'WHERE p.issue_date >= TRUNC(SYSDATE, ''YYYY'')',
'  AND p.issue_date < ADD_MONTHS(TRUNC(SYSDATE, ''YYYY''), 12)',
'GROUP BY',
'    CASE',
'        WHEN UPPER(TRIM(p.renewal_type)) = ''NUEVA''',
'            THEN ''Nuevas''',
'        WHEN UPPER(TRIM(p.renewal_type)) IN (''RENOVADA'')',
'            THEN ''Renovadas''',
'        ELSE ''Sin clasificar''',
'    END',
'ORDER BY valor DESC;'))
,p_series_name_column_name=>'NOMBRE_SERIE'
,p_items_value_column_name=>'VALOR'
,p_items_label_column_name=>'ETIQUETA'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
,p_threshold_display=>'onIndicator'
);
