,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2531463326621247859
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_menu_id=>wwv_flow_imp.id(33248841962653149)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4072363345357175094
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(33297196141720710)
,p_plug_name=>'Polizas'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    pol.id,',
'    pol.policy_id,',
'    pol.customer_id,',
'    c.full_name,',
'    pol.product_type_id,',
'    p.product_name,',
'    pol.insurer_id,',
'    ins.insurer_name,',
'    pol.expiration_date,',
'',
'    CASE UPPER(TRIM(pol.renewal_type))',
'        WHEN ''NEW''         THEN ''NUEVA''',
'        WHEN ''RENEWED''     THEN ''RENOVADA''',
'        WHEN ''NOT RENEWED'' THEN ''NO RENOVADA''',
'        ELSE UPPER(TRIM(pol.renewal_type))',
'    END AS renewal_type_display,',
'',
'    prev.policy_id AS previous_policy_number,',
'',
'    CASE UPPER(TRIM(pol.status))',
'        WHEN ''CURRENT''   THEN ''VIGENTE''',
'        WHEN ''EXPIRED''   THEN ''VENCIDA''',
'        WHEN ''CANCELLED'' THEN ''CANCELADA''',
'        WHEN ''ARCHIVED''  THEN ''ARCHIVADA''',
'        ELSE UPPER(TRIM(pol.status))',
'    END AS status_display,',
'',
'    pol.premium_amount',
'',
'FROM policies pol',
'',
'LEFT JOIN customers c',
'    ON c.id = pol.customer_id',
'',
'LEFT JOIN product_types p',
'    ON p.id = pol.product_type_id',
'',
'LEFT JOIN insurers ins',
'    ON ins.id = pol.insurer_id',
'',
'LEFT JOIN policies prev',
'    ON prev.id = pol.renewed_from_policy_id',
'',
'WHERE :P22_POLICY_STATUS = ''ALL''',
'   OR NVL(UPPER(TRIM(pol.status)), ''CURRENT'')',
'      = UPPER(TRIM(:P22_POLICY_STATUS))',
'',
'ORDER BY pol.expiration_date DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P22_POLICY_STATUS'
,p_prn_page_header=>'Polizas'
);
