prompt --application/pages/page_00014
begin
wwv_flow_imp_page.create_page(
 p_id=>14
,p_name=>'Documentos'
,p_alias=>'DOCUMENTOS'
,p_page_mode=>'MODAL'
,p_step_title=>'Documentos'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(document)',
'    .off("click.deleteDocument", ".js-delete-document")',
'    .on("click.deleteDocument", ".js-delete-document", function () {',
'',
'        const sourceType = this.dataset.sourceType;',
'        const documentId = this.dataset.documentId;',
'',
'        apex.message.confirm(',
unistr('            "\00BFEst\00E1 seguro de que desea eliminar este documento?",'),
'            function (confirmed) {',
'',
'                if (!confirmed) {',
'                    return;',
'                }',
'',
'                apex.server.process(',
'                    "ELIMINAR_DOCUMENTO",',
'                    {',
'                        x01: sourceType,',
'                        x02: documentId,',
'                        pageItems: "#P14_CUSTOMER_ID,#P14_POLICY_ID"',
'                    },',
'                    {',
'                        dataType: "text",',
'',
'                        success: function () {',
'                            apex.message.showPageSuccess(',
'                                "Documento eliminado correctamente."',
'                            );',
'',
'                            const region = apex.region("documentos-region");',
'',
'                            if (region) {',
'                                region.refresh();',
'                            }',
'                        },',
'',
'                        error: function (request) {',
'                            console.error(request.responseText);',
'',
'                            apex.message.alert(',
'                                "No se pudo eliminar el documento."',
'                            );',
'                        }',
'                    }',
'                );',
'            }',
'        );',
'    });'))
,p_page_template_options=>'#DEFAULT#'
,p_dialog_resizable=>'Y'
,p_protection_level=>'C'
,p_page_component_map=>'03'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(33404659257356680)
,p_name=>'Documentos'
,p_region_name=>'documentos-region'
,p_template=>4072358936313175081
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    x.id,',
'    x.source_type,',
'    x.tipo_documento,',
'    x.nombre_documento,',
'',
'    CASE',
'        WHEN LOWER(TRIM(x.mime_type)) LIKE ''image/%'' THEN',
'            ''<img src="'' ||',
'            apex_escape.html_attribute(',
'                document_file_url(',
'                    x.source_type,',
'                    x.id,',
'                    ''VIEW''',
'                )',
'            ) ||',
'            ''" alt="'' ||',
'            apex_escape.html_attribute(x.nombre_documento) ||',
'            ''" style="',
'                max-width:100%;',
'                max-height:500px;',
'                object-fit:contain;',
'                border-radius:8px;',
'            ">''',
'',
'        WHEN LOWER(TRIM(x.mime_type)) = ''application/pdf'' THEN',
'            ''<iframe src="'' ||',
'            apex_escape.html_attribute(',
'                document_file_url(',
'                    x.source_type,',
'                    x.id,',
'                    ''VIEW''',
'                )',
'            ) ||',
'            ''" title="Vista previa del documento"',
'               style="',
'                   width:100%;',
'                   height:500px;',
'                   border:1px solid #ddd;',
'                   border-radius:8px;',
'               ">',
'             </iframe>''',
'',
'        ELSE',
'            ''<em>Vista previa no disponible.</em>''',
'    END AS vista_previa,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                x.source_type,',
'                x.id,',
'                ''DOWNLOAD''',
'            )',
'        ) ||',
'        ''">',
'        <span class="fa fa-download" aria-hidden="true"></span>',
'        Descargar',
'     </a>'' AS descargar,',
'',
'    ''<button type="button"',
'             class="t-Button t-Button--small t-Button--danger js-delete-document"',
'             data-source-type="'' ||',
'             apex_escape.html_attribute(x.source_type) ||',
'             ''"',
'             data-document-id="'' ||',
'             apex_escape.html_attribute(x.id) ||',
'             ''">',
'        <span class="fa fa-trash" aria-hidden="true"></span>',
'        Eliminar',
'     </button>'' AS eliminar',
'',
'FROM (',
'    SELECT',
'        ''CUSTOMER'' AS source_type,',
'        cd.id,',
'        dt.document_type_name AS tipo_documento,',
'        NVL(cd.document_title, cd.file_name) AS nombre_documento,',
'        cd.mime_type,',
'        cd.uploaded_at',
'    FROM customer_documents cd',
'    JOIN document_types dt',
'      ON dt.id = cd.document_type_id',
'    WHERE cd.customer_id = :P14_CUSTOMER_ID',
'      AND :P14_CUSTOMER_ID IS NOT NULL',
'      AND cd.is_current = ''Y''',
'      AND NVL(cd.deleted_yn, ''N'') = ''N''',
'',
'    UNION ALL',
'',
'    SELECT',
'        ''POLICY'' AS source_type,',
'        pd.id,',
'        dt.document_type_name AS tipo_documento,',
'        NVL(pd.document_title, pd.file_name) AS nombre_documento,',
'        pd.mime_type,',
'        pd.uploaded_at',
'    FROM policy_documents pd',
'    JOIN document_types dt',
'      ON dt.id = pd.document_type_id',
'    WHERE pd.policy_id = :P14_POLICY_ID',
'      AND :P14_POLICY_ID IS NOT NULL',
'      AND pd.is_current = ''Y''',
'      AND NVL(pd.deleted_yn, ''N'') = ''N''',
') x',
'',
'ORDER BY',
'    x.tipo_documento,',
'    x.uploaded_at DESC;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
