wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36926069207613671)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ELIMINAR_DOCUMENTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_document_id NUMBER;',
'    v_source_type VARCHAR2(20);',
'BEGIN',
'    v_document_id := TO_NUMBER(apex_application.g_x02);',
'    v_source_type := UPPER(TRIM(apex_application.g_x01));',
'',
'    IF v_source_type = ''CUSTOMER'' THEN',
'',
'        UPDATE customer_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = v_document_id',
'           AND customer_id = :P14_CUSTOMER_ID',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSIF v_source_type = ''POLICY'' THEN',
'',
'        UPDATE policy_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = v_document_id',
'           AND policy_id = :P14_POLICY_ID',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSE',
'        raise_application_error(',
'            -20001,',
unistr('            ''Tipo de documento no v\00E1lido.'''),
'        );',
'    END IF;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        raise_application_error(',
'            -20002,',
'            ''El documento no existe, ya fue eliminado o no pertenece al registro actual.''',
'        );',
'    END IF;',
'',
'EXCEPTION',
'    WHEN VALUE_ERROR THEN',
'        raise_application_error(',
'            -20003,',
unistr('            ''El identificador del documento no es v\00E1lido.'''),
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13412656166978716
);
end;
/
