wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33405500752356688)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Mostrar archivo inline'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file       BLOB;',
'    l_mime_type  VARCHAR2(255);',
'    l_file_name  VARCHAR2(255);',
'    l_inline     BOOLEAN;',
'BEGIN',
'    IF :P15_SOURCE_TYPE = ''CUSTOMER'' THEN',
'',
'        SELECT file_content,',
'               mime_type,',
'               file_name',
'          INTO l_file,',
'               l_mime_type,',
'               l_file_name',
'          FROM customer_documents',
'         WHERE id = :P15_ID;',
'',
'    ELSIF :P15_SOURCE_TYPE = ''POLICY'' THEN',
'',
'        SELECT file_content,',
'               mime_type,',
'               file_name',
'          INTO l_file,',
'               l_mime_type,',
'               l_file_name',
'          FROM policy_documents',
'         WHERE id = :P15_ID;',
'',
'    ELSE',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invalid document source''',
'        );',
'    END IF;',
'',
'    l_inline := :P15_ACTION = ''VIEW'';',
'',
'    apex_http.download(',
'        p_blob         => l_file,',
'        p_content_type => l_mime_type,',
'        p_filename     => l_file_name,',
'        p_is_inline    => l_inline',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9892087711721733
);
end;
