wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(49543522248838815)
,p_plug_name=>'Documentos'
,p_title=>'Documentos'
,p_region_name=>'customer-documents-region'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''CUSTOMER'' AS source_type,',
'    cd.id      AS document_id,',
'    ''Cliente''  AS origen,',
'    c.full_name AS propietario,',
'    dt.document_type_name AS tipo_documento,',
'    NVL(cd.document_title, cd.file_name) AS nombre_documento,',
'    cd.version_number,',
'    TO_CHAR(cd.uploaded_at,''DD/MM/YYYY'') AS uploaded_at,',
'    cd.uploaded_by,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                ''CUSTOMER'',',
'                cd.id,',
'                ''VIEW''',
'            )',
'        ) ||',
'        ''" target="_blank">',
'        <span class="fa fa-eye" aria-hidden="true"></span>',
'        Ver',
'     </a>'' AS ver,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                ''CUSTOMER'',',
'                cd.id,',
'                ''DOWNLOAD''',
'            )',
'        ) ||',
'        ''">',
'        <span class="fa fa-download" aria-hidden="true"></span>',
'        Descargar',
'     </a>'' AS descargar,',
'',
'    ''<button type="button"',
'             class="t-Button t-Button--small t-Button--danger js-delete-document"',
'             data-source-type="CUSTOMER"',
'             data-document-id="'' ||',
'             apex_escape.html_attribute(TO_CHAR(cd.id)) ||',
'             ''">',
'        <span class="fa fa-trash" aria-hidden="true"></span>',
'        Eliminar',
'     </button>'' AS eliminar',
'',
'FROM customer_documents cd',
'',
'JOIN customers c',
'    ON c.id = cd.customer_id',
'',
'JOIN document_types dt',
'    ON dt.id = cd.document_type_id',
'',
'WHERE cd.customer_id = :P17_ID',
'  AND :P17_ID IS NOT NULL',
'  AND dt.document_scope = ''CLIENTE''',
'  AND cd.is_current = ''Y''',
'  AND NVL(cd.deleted_yn, ''N'') = ''N''',
'',
'ORDER BY',
'    dt.document_type_name,',
'    cd.uploaded_at DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P17_ID'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P17_ID'
