prompt --application/pages/page_00022
begin
wwv_flow_imp_page.create_page(
 p_id=>22
,p_name=>'Formulario Poliza'
,p_alias=>'FORMULARIO-POLIZA'
,p_step_title=>'Formulario Poliza'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(document)',
'    .off("click.deleteDocument", ".js-delete-document")',
'    .on("click.deleteDocument", ".js-delete-document", function () {',
'',
'        const sourceType = this.dataset.sourceType;',
'        const documentId = this.dataset.documentId;',
'',
'        apex.message.confirm(',
unistr('            "\00BFEst\00E1 seguro de que desea enviar este documento a la papelera?",'),
'            function (confirmed) {',
'',
'                if (!confirmed) {',
'                    return;',
'                }',
'',
'                apex.server.process(',
'                    "ELIMINAR_DOCUMENTO",',
'                    {',
'                        x01: sourceType,',
'                        x02: documentId',
'                    },',
'                    {',
'                        dataType: "json",',
'',
'                        success: function (data) {',
'',
'                            if (!data || data.success !== true) {',
'                                apex.message.alert(',
unistr('                                    "El servidor no confirm\00F3 la eliminaci\00F3n."'),
'                                );',
'                                return;',
'                            }',
'',
'                            const region =',
'                                apex.region("policy-documents-region");',
'',
'                            if (region) {',
'                                region.refresh();',
'                            } else {',
'                                console.error(',
unistr('                                    "No se encontr\00F3 la regi\00F3n policy-documents-region."'),
'                                );',
'                            }',
'',
'                            apex.message.showPageSuccess(',
'                                "Documento enviado a la papelera."',
'                            );',
'                        },',
'',
'                        error: function (request, status, error) {',
'                            console.error(',
'                                request.responseText,',
'                                status,',
'                                error',
'                            );',
'',
'                            apex.message.alert(',
'                                "No se pudo eliminar el documento."',
'                            );',
'                        }',
'                    }',
'                );',
'            }',
'        );',
'    });'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'02'
);
