,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''POLICY'' AS source_type,',
'    pd.id    AS document_id,',
unistr('    ''P\00F3liza'' AS origen,'),
'',
'    NVL(',
unistr('        c.full_name || '' \2014 P\00F3liza '' || p.policy_id,'),
unistr('        ''P\00F3liza '' || p.policy_id'),
'    ) AS propietario,',
'',
'    dt.document_type_name AS tipo_documento,',
'    NVL(pd.document_title, pd.file_name) AS nombre_documento,',
'    pd.version_number,',
'    TO_CHAR(pd.uploaded_at, ''DD/MM/YYYY'') AS uploaded_at,',
'    pd.uploaded_by,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                ''POLICY'',',
'                pd.id,',
'                ''VIEW''',
'            )',
'        ) ||',
'        ''" target="_blank">',
'        <span class="fa fa-eye" aria-hidden="true"></span>',
'        Ver',
'     </a>'' AS ver,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                ''POLICY'',',
'                pd.id,',
'                ''DOWNLOAD''',
'            )',
'        ) ||',
'        ''">',
'        <span class="fa fa-download" aria-hidden="true"></span>',
'        Descargar',
'     </a>'' AS descargar,',
'',
'    ''<button type="button"',
'             class="t-Button t-Button--small t-Button--danger js-delete-document"',
'             data-source-type="POLICY"',
'             data-document-id="'' ||',
'             apex_escape.html_attribute(TO_CHAR(pd.id)) ||',
'             ''">',
'        <span class="fa fa-trash" aria-hidden="true"></span>',
'        Eliminar',
'     </button>'' AS eliminar',
'',
'FROM policy_documents pd',
'JOIN policies p',
'    ON p.id = pd.policy_id',
'LEFT JOIN customers c',
'    ON c.id = p.customer_id',
'JOIN document_types dt',
'    ON dt.id = pd.document_type_id',
'',
'WHERE pd.policy_id = :P22_ID',
'  AND :P22_ID IS NOT NULL',
'  AND dt.document_scope = ''POLIZA''',
'  AND pd.is_current = ''Y''',
'  AND NVL(pd.deleted_yn, ''N'') = ''N''',
'',
'ORDER BY',
'    dt.document_type_name,',
'    pd.uploaded_at DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P22_ID'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P22_ID'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
