wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(39688554757656670)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ELIMINAR_DOCUMENTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_document_id NUMBER;',
'    l_source_type VARCHAR2(20);',
'    l_rows        PLS_INTEGER := 0;',
'BEGIN',
'    l_document_id := TO_NUMBER(apex_application.g_x02);',
'    l_source_type := UPPER(TRIM(apex_application.g_x01));',
'',
'    IF l_source_type = ''CUSTOMER'' THEN',
'',
'        UPDATE customer_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = l_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'        l_rows := SQL%ROWCOUNT;',
'',
'    ELSIF l_source_type = ''POLICY'' THEN',
'',
'        UPDATE policy_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = l_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'        l_rows := SQL%ROWCOUNT;',
'',
'    ELSE',
'        raise_application_error(',
'            -20001,',
unistr('            ''Tipo de documento no v\00E1lido: '' || l_source_type'),
'        );',
'    END IF;',
'',
'    IF l_rows = 0 THEN',
'        raise_application_error(',
'            -20002,',
unistr('            ''No se actualiz\00F3 ning\00FAn documento. ID recibido: '' ||'),
'            l_document_id || '', tipo: '' || l_source_type',
'        );',
'    END IF;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.write(''rows_updated'', l_rows);',
'    apex_json.write(''document_id'', l_document_id);',
'    apex_json.write(''source_type'', l_source_type);',
'    apex_json.close_object;',
'',
'EXCEPTION',
'    WHEN VALUE_ERROR THEN',
'        raise_application_error(',
'            -20003,',
unistr('            ''El identificador recibido no es num\00E9rico: '' ||'),
'            apex_application.g_x02',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>16175141717021715
);
end;
