wwv_flow_imp_page.create_page(
 p_id=>23
,p_name=>unistr('Gesti\00F3n de documentos')
,p_alias=>'GESTION-DOCUMENTOS'
,p_step_title=>unistr('Gesti\00F3n de documentos')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function ($) {',
'',
'    function refreshDocumentRegions() {',
'        const currentRegion =',
'            apex.region("documentos-actuales-region");',
'',
'        const historyRegion =',
'            apex.region("documentos-historial-region");',
'',
'        const deletedRegion =',
'            apex.region("documentos-eliminados-region");',
'',
'        if (currentRegion) {',
'            currentRegion.refresh();',
'        }',
'',
'        if (historyRegion) {',
'            historyRegion.refresh();',
'        }',
'',
'        if (deletedRegion) {',
'            deletedRegion.refresh();',
'        }',
'    }',
'',
'',
'    /*',
'     * Eliminar documento actual',
'     */',
'    $(document)',
'        .off("click.deleteDocument", ".js-delete-document")',
'        .on("click.deleteDocument", ".js-delete-document", function () {',
'',
'            const sourceType = this.dataset.sourceType;',
'            const documentId = this.dataset.documentId;',
'',
'            apex.message.confirm(',
unistr('                "\00BFDesea enviar este documento a la papelera?",'),
'                function (confirmed) {',
'',
'                    if (!confirmed) {',
'                        return;',
'                    }',
'',
'                    apex.server.process(',
'                        "ELIMINAR_DOCUMENTO",',
'                        {',
'                            x01: sourceType,',
'                            x02: documentId',
'                        },',
'                        {',
'                            dataType: "text",',
'',
'                            success: function () {',
'                                apex.message.showPageSuccess(',
'                                    "Documento enviado a la papelera."',
'                                );',
'',
'                                refreshDocumentRegions();',
'                            },',
'',
'                            error: function (request) {',
'                                console.error(request.responseText);',
'',
'                                apex.message.alert(',
'                                    "No se pudo eliminar el documento."',
'                                );',
'                            }',
'                        }',
'                    );',
'                }',
'            );',
'        });',
'',
'',
'    /*',
unistr('     * Restaurar documento eliminado como versi\00F3n actual'),
'     */',
'    $(document)',
'        .off("click.restoreDocument", ".js-restore-document")',
'        .on("click.restoreDocument", ".js-restore-document", function () {',
'',
'            const sourceType = this.dataset.sourceType;',
'            const documentId = this.dataset.documentId;',
'',
'            apex.message.confirm(',
unistr('                "\00BFDesea restaurar este documento como la versi\00F3n actual?",'),
'                function (confirmed) {',
'',
'                    if (!confirmed) {',
'                        return;',
'                    }',
'',
'                    apex.server.process(',
'                        "RESTAURAR_DOCUMENTO",',
'                        {',
'                            x01: sourceType,',
'                            x02: documentId',
'                        },',
'                        {',
'                            dataType: "text",',
'',
'                            success: function () {',
'                                apex.message.showPageSuccess(',
'                                    "Documento restaurado correctamente."',
'                                );',
'',
'                                refreshDocumentRegions();',
'                            },',
'',
'                            error: function (request) {',
'                                console.error(request.responseText);',
'',
'                                apex.message.alert(',
'                                    "No se pudo restaurar el documento."',
'                                );',
'                            }',
'                        }',
'                    );',
'                }',
'            );',
'        });',
'',
'',
'    /*',
unistr('     * Establecer una versi\00F3n hist\00F3rica como actual'),
'     */',
'    $(document)',
'        .off("click.makeCurrent", ".js-make-current")',
'        .on("click.makeCurrent", ".js-make-current", function () {',
'',
'            const sourceType = this.dataset.sourceType;',
'            const documentId = this.dataset.documentId;',
'',
'            apex.message.confirm(',
unistr('                "\00BFDesea establecer esta versi\00F3n como el documento actual?",'),
'                function (confirmed) {',
'',
'                    if (!confirmed) {',
'                        return;',
'                    }',
'',
'                    apex.server.process(',
'                        "ESTABLECER_DOCUMENTO_ACTUAL",',
'                        {',
'                            x01: sourceType,',
'                            x02: documentId',
'                        },',
'                        {',
'                            dataType: "text",',
'',
'                            success: function () {',
'                                apex.message.showPageSuccess(',
unistr('                                    "La versi\00F3n fue establecida como actual."'),
'                                );',
'',
'                                refreshDocumentRegions();',
'                            },',
'',
'                            error: function (request) {',
'                                console.error(request.responseText);',
'',
'                                apex.message.alert(',
unistr('                                    "No se pudo establecer la versi\00F3n como actual."'),
'                                );',
'                            }',
'                        }',
'                    );',
'                }',
'            );',
'        });',
'',
'})(apex.jQuery);'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
