wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(36928102499613691)
,p_plug_name=>'Documentos actuales'
,p_region_name=>'documentos-actuales-region'
,p_parent_plug_id=>wwv_flow_imp.id(36926627361613677)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    x.source_type,',
'    x.document_id,',
'    x.origen,',
'    x.propietario,',
'    x.tipo_documento,',
'    x.nombre_documento,',
'    x.version_number,',
'    x.uploaded_at,',
'    x.uploaded_by,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                x.source_type,',
'                x.document_id,',
'                ''VIEW''',
'            )',
'        ) ||',
'        ''" target="_blank">',
'        <span class="fa fa-eye" aria-hidden="true"></span>',
'        Ver',
'     </a>'' AS ver,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                x.source_type,',
'                x.document_id,',
'                ''DOWNLOAD''',
'            )',
'        ) ||',
'        ''">',
'        <span class="fa fa-download" aria-hidden="true"></span>',
'        Descargar',
'     </a>'' AS descargar,',
'',
'    ''<button type="button"',
'             class="t-Button t-Button--small t-Button--danger js-delete-document"',
'             data-source-type="'' ||',
'             apex_escape.html_attribute(x.source_type) ||',
'             ''"',
'             data-document-id="'' ||',
'             apex_escape.html_attribute(x.document_id) ||',
'             ''">',
'        <span class="fa fa-trash" aria-hidden="true"></span>',
'        Eliminar',
'     </button>'' AS eliminar',
'',
'FROM (',
'    SELECT',
'        ''CUSTOMER'' AS source_type,',
'        cd.id AS document_id,',
'        ''Cliente'' AS origen,',
'        c.full_name AS propietario,',
'        dt.document_type_name AS tipo_documento,',
'        NVL(cd.document_title, cd.file_name) AS nombre_documento,',
'        cd.version_number,',
'        cd.uploaded_at,',
'        cd.uploaded_by',
'    FROM customer_documents cd',
