,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    x.source_type,',
'    x.document_id,',
'    x.origen,',
'    x.propietario,',
'    x.tipo_documento,',
'    x.nombre_documento,',
'    x.version_number,',
'    x.uploaded_at,',
'    x.uploaded_by,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                x.source_type,',
'                x.document_id,',
'                ''VIEW''',
'            )',
'        ) ||',
'        ''" target="_blank">',
'        <span class="fa fa-eye" aria-hidden="true"></span>',
'        Ver',
'     </a>'' AS ver,',
'',
'    ''<a class="t-Button t-Button--small"',
'        href="'' ||',
'        apex_escape.html_attribute(',
'            document_file_url(',
'                x.source_type,',
'                x.document_id,',
'                ''DOWNLOAD''',
'            )',
'        ) ||',
'        ''">',
'        <span class="fa fa-download" aria-hidden="true"></span>',
'        Descargar',
'     </a>'' AS descargar,',
'',
'    ''<button type="button"',
'             class="t-Button t-Button--small t-Button--hot js-make-current"',
'             data-source-type="'' ||',
'             apex_escape.html_attribute(x.source_type) ||',
'             ''"',
'             data-document-id="'' ||',
'             apex_escape.html_attribute(x.document_id) ||',
'             ''">',
'        <span class="fa fa-check-circle" aria-hidden="true"></span>',
'        Establecer como actual',
'     </button>'' AS establecer_actual',
'',
'FROM (',
'    SELECT',
'        ''CUSTOMER'' AS source_type,',
'        cd.id AS document_id,',
'        ''Cliente'' AS origen,',
'        c.full_name AS propietario,',
'        dt.document_type_name AS tipo_documento,',
'        NVL(cd.document_title, cd.file_name) AS nombre_documento,',
'        cd.version_number,',
'        cd.uploaded_at,',
'        cd.uploaded_by',
'    FROM customer_documents cd',
'    JOIN customers c',
'      ON c.id = cd.customer_id',
'    JOIN document_types dt',
'      ON dt.id = cd.document_type_id',
'    WHERE cd.is_current = ''N''',
'      AND NVL(cd.deleted_yn, ''N'') = ''N''',
'',
'    UNION ALL',
'',
'    SELECT',
'        ''POLICY'' AS source_type,',
'        pd.id AS document_id,',
unistr('        ''P\00F3liza'' AS origen,'),
'        NVL(',
unistr('            c.full_name || '' \2014 P\00F3liza '' || TO_CHAR(p.policy_id),'),
unistr('            ''P\00F3liza '' || TO_CHAR(p.policy_id)'),
'        ) AS propietario,',
'        dt.document_type_name AS tipo_documento,',
'        NVL(pd.document_title, pd.file_name) AS nombre_documento,',
'        pd.version_number,',
'        pd.uploaded_at,',
'        pd.uploaded_by',
'    FROM policy_documents pd',
'    JOIN policies p',
'      ON p.id = pd.policy_id',
'    LEFT JOIN customers c',
'      ON c.id = p.customer_id',
'    JOIN document_types dt',
'      ON dt.id = pd.document_type_id',
'    WHERE pd.is_current = ''N''',
'      AND NVL(pd.deleted_yn, ''N'') = ''N''',
') x',
'',
'ORDER BY',
'    x.tipo_documento,',
'    x.propietario,',
'    x.version_number DESC,',
'    x.uploaded_at DESC;'))
,p_plug_source_type=>'NATIVE_IR'
