 p_id=>wwv_flow_imp.id(37638235977118581)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ELIMINAR_DOCUMENTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_document_id NUMBER;',
'    v_source_type VARCHAR2(20);',
'BEGIN',
'    v_document_id := TO_NUMBER(apex_application.g_x02);',
'    v_source_type := UPPER(TRIM(apex_application.g_x01));',
'',
'    IF v_source_type = ''CUSTOMER'' THEN',
'',
'        UPDATE customer_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSIF v_source_type = ''POLICY'' THEN',
'',
'        UPDATE policy_documents',
'           SET is_current    = ''N'',',
'               deleted_yn    = ''Y'',',
'               deleted_at    = SYSTIMESTAMP,',
'               deleted_by    = :APP_USER,',
'               delete_reason = ''Eliminado por el usuario''',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSE',
'        raise_application_error(',
'            -20001,',
unistr('            ''Tipo de documento no v\00E1lido.'''),
'        );',
'    END IF;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        raise_application_error(',
'            -20002,',
'            ''El documento no existe o ya fue eliminado.''',
'        );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14124822936483626
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37638332692118582)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ESTABLECER_DOCUMENTO_ACTUAL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_document_id      NUMBER;',
'    v_source_type      VARCHAR2(20);',
'    v_customer_id      NUMBER;',
'    v_policy_id        NUMBER;',
'    v_document_type_id NUMBER;',
'BEGIN',
'    v_document_id := TO_NUMBER(apex_application.g_x02);',
'    v_source_type := UPPER(TRIM(apex_application.g_x01));',
'',
'    IF v_source_type = ''CUSTOMER'' THEN',
'',
'        SELECT customer_id,',
'               document_type_id',
'          INTO v_customer_id,',
'               v_document_type_id',
'          FROM customer_documents',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'        UPDATE customer_documents',
'           SET is_current = ''N''',
'         WHERE customer_id = v_customer_id',
'           AND document_type_id = v_document_type_id',
'           AND is_current = ''Y'';',
'',
'        UPDATE customer_documents',
'           SET is_current = ''Y''',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSIF v_source_type = ''POLICY'' THEN',
'',
'        SELECT policy_id,',
'               document_type_id',
'          INTO v_policy_id,',
'               v_document_type_id',
'          FROM policy_documents',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'        UPDATE policy_documents',
'           SET is_current = ''N''',
'         WHERE policy_id = v_policy_id',
'           AND document_type_id = v_document_type_id',
'           AND is_current = ''Y'';',
'',
'        UPDATE policy_documents',
'           SET is_current = ''Y''',
'         WHERE id = v_document_id',
'           AND NVL(deleted_yn, ''N'') = ''N'';',
'',
'    ELSE',
'        raise_application_error(',
'            -20001,',
unistr('            ''Tipo de documento no v\00E1lido.'''),
'        );',
'    END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        raise_application_error(',
'            -20002,',
'            ''El documento no existe o fue eliminado.''',
'        );',
'',
'    WHEN VALUE_ERROR THEN',
'        raise_application_error(',
'            -20003,',
unistr('            ''El identificador del documento no es v\00E1lido.'''),
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14124919651483627
);
end;
