,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    c.id,',
'    c.full_name,',
'    c.last_name,',
'    c.first_name,',
'    c.organization,',
'    c.national_id,',
'    c.phone_primary,',
'    c.phone_secondary,',
'    c.whatsapp_e164,',
'    c.source_id,',
'    s.source_name,',
'',
'    c.lifecycle_stage AS lifecycle_stage_id,',
'    e.estado_name     AS lifecycle_stage,',
'',
'    c.status,',
'    c.notes,',
'    c.email,',
'',
'    CASE c.tipo_cliente',
unistr('        WHEN ''F'' THEN ''F\00EDsica'''),
unistr('        WHEN ''J'' THEN ''Jur\00EDdica'''),
'        ELSE ''Sin tipo de cliente''',
'    END AS tipo_cliente',
'',
'FROM customers c',
'',
'LEFT JOIN sources s',
'    ON s.id = c.source_id',
'',
'LEFT JOIN estados e',
'    ON e.estado_id = c.lifecycle_stage',
'',
'WHERE :P25_CUSTOMER_STATUS = ''ALL''',
'   OR NVL(UPPER(TRIM(c.status)), ''ACTIVE'')',
'      = UPPER(TRIM(:P25_CUSTOMER_STATUS))',
'',
'ORDER BY c.full_name;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P25_CUSTOMER_STATUS'
,p_prn_page_header=>'Clientes'
