);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(36415854410040007)
,p_plug_name=>unistr('Producci\00F3n de Primas')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    t.target_year AS anio,',
'    t.target_month AS mes_numero,',
'',
'    INITCAP(',
'        TRIM(',
'            TO_CHAR(',
'                TO_DATE(t.target_month, ''MM''),',
'                ''Month'',',
'                ''NLS_DATE_LANGUAGE=SPANISH''',
'            )',
'        )',
'    ) AS mes,',
'',
'    pt.product_name AS producto,',
'    i.insurer_name AS compania,',
'',
'    t.target_premium AS meta_prima,',
'',
'    NVL(SUM(p.premium_amount), 0) AS produccion_real,',
'',
'    NVL(SUM(p.premium_amount), 0)',
'        - t.target_premium AS diferencia,',
'',
'    ROUND(',
'        CASE',
'            WHEN NVL(t.target_premium, 0) = 0 THEN 0',
'            ELSE NVL(SUM(p.premium_amount), 0)',
'                 / t.target_premium',
'                 * 100',
'        END,',
'        2',
'    ) AS porcentaje_alcanzado',
'',
'FROM production_targets t',
'',
'JOIN product_types pt',
'    ON pt.id = t.product_type_id',
'',
'JOIN insurers i',
'    ON i.id = t.insurer_id',
'',
'LEFT JOIN policies p',
'    ON p.product_type_id = t.product_type_id',
'   AND p.insurer_id = t.insurer_id',
'   AND EXTRACT(YEAR FROM p.issue_date) = t.target_year',
'   AND EXTRACT(MONTH FROM p.issue_date) = t.target_month',
'',
'GROUP BY',
'    t.target_year,',
'    t.target_month,',
'    pt.product_name,',
'    i.insurer_name,',
'    t.target_premium',
'',
'ORDER BY',
'    t.target_year DESC,',
'    t.target_month DESC,',
'    i.insurer_name,',
'    pt.product_name;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Metas'
);
