,p_plug_name=>unistr('P\00F3lizas que vencen pronto')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    p.id AS policy_id,',
'    p.policy_id AS numero_poliza,',
'    c.full_name AS cliente,',
'    c.phone_primary AS telefono,',
'    pt.product_name AS producto,',
'    i.insurer_name AS compania,',
'    p.expiration_date AS vencimiento,',
'    p.status AS estado,',
'    p.premium_amount AS prima,',
'    TRUNC(p.expiration_date) - TRUNC(SYSDATE) AS dias_restantes,',
'',
'    CASE',
'        WHEN TRUNC(p.expiration_date) - TRUNC(SYSDATE) <= 30',
'        THEN',
'            ''https://wa.me/595972251387?text='' ||',
'            APEX_UTIL.URL_ENCODE(',
'                ''Hola, este es un recordatorio de prueba desde el CRM.'' ||',
'                CHR(10) || CHR(10) ||',
unistr('                ''La p\00F3liza N\00B0 '' || p.policy_id ||'),
'                '' del cliente '' || c.full_name ||',
'                '' vence el '' || TO_CHAR(p.expiration_date, ''DD/MM/YYYY'') || ''.'' ||',
'                CHR(10) || CHR(10) ||',
'                ''Producto: '' || pt.product_name || CHR(10) ||',
unistr('                ''Compa\00F1\00EDa: '' || i.insurer_name || CHR(10) || CHR(10) ||'),
unistr('                ''\00BFDesea que preparemos la renovaci\00F3n?'''),
'            )',
'    END AS whatsapp_link',
'',
'FROM policies p',
'JOIN customers c',
'    ON c.id = p.customer_id',
'JOIN product_types pt',
'    ON pt.id = p.product_type_id',
'JOIN insurers i',
'    ON i.id = p.insurer_id',
'',
'WHERE p.expiration_date BETWEEN TRUNC(SYSDATE)',
'                            AND TRUNC(SYSDATE) + 90',
'',
'ORDER BY p.expiration_date;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Reporte General de Clientes'
);
