,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2531463326621247859
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_menu_id=>wwv_flow_imp.id(33248841962653149)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4072363345357175094
,p_ai_enabled=>false
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(49890665200945964)
,p_plug_name=>'Renovaciones'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    t.target_year AS anio,',
'    t.target_month AS mes_numero,',
'',
'    INITCAP(',
'        TRIM(',
'            TO_CHAR(',
'                TO_DATE(t.target_month, ''MM''),',
'                ''Month'',',
'                ''NLS_DATE_LANGUAGE=SPANISH''',
'            )',
'        )',
'    ) AS mes,',
'',
'    pt.product_name AS producto,',
'    i.insurer_name AS compania,',
'',
'    t.target_new_policies AS meta_polizas_nuevas,',
'',
'    COUNT(',
'        CASE',
'            WHEN UPPER(TRIM(p.renewal_type)) = ''NEW''',
'            THEN 1',
'        END',
'    ) AS polizas_nuevas,',
'',
'    COUNT(',
'        CASE',
'            WHEN UPPER(TRIM(p.renewal_type)) IN (',
'                ''RENEWED'',',
'                ''RENEWAL''',
'            )',
'            THEN 1',
'        END',
'    ) AS polizas_renovadas,',
'',
'    COUNT(p.id) AS total_polizas,',
'',
'    COUNT(',
'        CASE',
'            WHEN UPPER(TRIM(p.renewal_type)) = ''NEW''',
'            THEN 1',
'        END',
'    ) - t.target_new_policies AS diferencia_nuevas,',
'',
'    ROUND(',
'        CASE',
'            WHEN NVL(t.target_new_policies, 0) = 0 THEN 0',
'            ELSE COUNT(',
'                     CASE',
'                         WHEN UPPER(TRIM(p.renewal_type)) = ''NEW''',
'                         THEN 1',
'                     END',
'                 )',
'                 / t.target_new_policies',
'                 * 100',
'        END,',
'        2',
'    ) AS porcentaje_meta_nuevas',
'',
'FROM production_targets t',
'',
'JOIN product_types pt',
'    ON pt.id = t.product_type_id',
'',
'JOIN insurers i',
'    ON i.id = t.insurer_id',
'',
'LEFT JOIN policies p',
'    ON p.product_type_id = t.product_type_id',
'   AND p.insurer_id = t.insurer_id',
'   AND EXTRACT(YEAR FROM p.issue_date) = t.target_year',
'   AND EXTRACT(MONTH FROM p.issue_date) = t.target_month',
'',
'GROUP BY',
'    t.target_year,',
'    t.target_month,',
'    pt.product_name,',
'    i.insurer_name,',
'    t.target_new_policies',
'',
'ORDER BY',
'    t.target_year DESC,',
'    t.target_month DESC,',
'    i.insurer_name,',
'    pt.product_name;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Metas'
