wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(63191401148141539)
,p_plug_name=>'Reporte de Comisiones'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    EXTRACT(YEAR FROM p.issue_date) AS anio,',
'    EXTRACT(MONTH FROM p.issue_date) AS mes_numero,',
'',
'    INITCAP(',
'        TRIM(',
'            TO_CHAR(',
'                p.issue_date,',
'                ''Month'',',
'                ''NLS_DATE_LANGUAGE=SPANISH''',
'            )',
'        )',
'    ) AS mes,',
'',
'    pt.product_name AS producto,',
'    i.insurer_name AS compania,',
'',
'    COUNT(p.id) AS cantidad_polizas,',
'',
'    NVL(SUM(p.premium_amount), 0) AS prima_total,',
'',
'    NVL(SUM(p.commission_own), 0) AS comision_propia,',
'',
'    NVL(SUM(p.commission_third_party), 0) AS comision_terceros,',
'',
'    NVL(SUM(p.commission_own), 0)',
'        - NVL(SUM(p.commission_third_party), 0)',
'        AS comision_neta,',
'',
'    ROUND(',
'        CASE',
'            WHEN NVL(SUM(p.premium_amount), 0) = 0 THEN 0',
'            ELSE NVL(SUM(p.commission_own), 0)',
'                 / SUM(p.premium_amount)',
'                 * 100',
'        END,',
'        2',
'    ) AS porcentaje_comision',
'',
'FROM policies p',
'',
'JOIN product_types pt',
'    ON pt.id = p.product_type_id',
'',
'JOIN insurers i',
'    ON i.id = p.insurer_id',
'',
'WHERE p.issue_date IS NOT NULL',
'',
'GROUP BY',
'    EXTRACT(YEAR FROM p.issue_date),',
'    EXTRACT(MONTH FROM p.issue_date),',
'    TO_CHAR(',
'        p.issue_date,',
'        ''Month'',',
'        ''NLS_DATE_LANGUAGE=SPANISH''',
'    ),',
'    pt.product_name,',
'    i.insurer_name',
'',
'ORDER BY',
'    anio DESC,',
'    mes_numero DESC,',
'    i.insurer_name,',
'    pt.product_name;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
