'    c.id,',
'    c.full_name,',
'    c.last_name,',
'    c.first_name,',
'    c.organization,',
'    c.national_id,',
'    c.phone_primary,',
'    c.phone_secondary,',
'    c.whatsapp_e164,',
'    c.source_id,',
'    s.source_name,',
'    e.estado_name AS lifecycle_stage,',
'    c.status,',
'    c.notes,',
'    c.email,',
'',
'    CASE c.tipo_cliente',
unistr('        WHEN ''F'' THEN ''F\00EDsica'''),
unistr('        WHEN ''J'' THEN ''Jur\00EDdica'''),
'        ELSE ''Sin tipo de cliente''',
'    END AS tipo_cliente',
'',
'FROM customers c',
'',
'LEFT JOIN sources s',
'    ON s.id = c.source_id',
'',
'LEFT JOIN estados e',
'    ON e.estado_id = c.lifecycle_stage',
'',
'ORDER BY c.full_name;'))
