wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(63249258956249849)
,p_plug_name=>unistr('Cartera de P\00F3lizas')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    pol.id,',
'    pol.policy_id,',
'    pol.customer_id,',
'    c.full_name AS cliente,',
'',
'    pol.product_type_id,',
'    p.product_name AS tipo_seguro,',
'',
'    pol.insurer_id,',
'    ins.insurer_name AS compania,',
'',
'    pol.issue_date,',
'    pol.expiration_date,',
'',
'    CASE UPPER(TRIM(pol.status))',
'        WHEN ''CURRENT''   THEN ''VIGENTE''',
'        WHEN ''EXPIRED''   THEN ''VENCIDA''',
'        WHEN ''CANCELLED'' THEN ''CANCELADA''',
'        WHEN ''ARCHIVED''  THEN ''ARCHIVADA''',
'        ELSE UPPER(TRIM(pol.status))',
'    END AS estado_poliza,',
'',
'    CASE UPPER(TRIM(pol.renewal_type))',
'        WHEN ''NEW''         THEN ''NUEVA''',
'        WHEN ''RENEWED''     THEN ''RENOVADA''',
'        WHEN ''NOT_RENEWED'' THEN ''NO RENOVADA''',
'        WHEN ''NOT RENEWED'' THEN ''NO RENOVADA''',
'        ELSE NULL',
'    END AS tipo_renovacion,',
'',
'    NVL(TO_CHAR(prev.policy_id), ''-'') AS poliza_anterior,',
'',
'    pol.premium_amount,',
'    pol.commission_own,',
'    pol.commission_third_party,',
'',
'    TRUNC(pol.expiration_date) - TRUNC(SYSDATE) AS dias_restantes',
'',
'FROM policies pol',
'',
'LEFT JOIN customers c',
'    ON c.id = pol.customer_id',
'',
'LEFT JOIN product_types p',
'    ON p.id = pol.product_type_id',
'',
'LEFT JOIN insurers ins',
'    ON ins.id = pol.insurer_id',
'',
'LEFT JOIN policies prev',
'    ON prev.id = pol.renewed_from_policy_id',
'',
'WHERE NVL(UPPER(TRIM(pol.status)), ''CURRENT'') <> ''ARCHIVED''',
'',
'ORDER BY pol.expiration_date DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Reporte General de Clientes'
,p_ai_enabled=>false
);
