wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(36864964164999288)
,p_plug_name=>'Resumen General'
,p_region_name=>'dashboard_cards'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''Clientes'' AS titulo,',
'    TO_CHAR(COUNT(*), ''FM999G999G990'') AS valor,',
'    ''fa fa-users'' AS icono,',
'    1 AS orden',
'FROM customers',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''P\00F3lizas Vigentes'','),
'    TO_CHAR(COUNT(*), ''FM999G999G990''),',
'    ''fa fa-file-text'',',
'    2',
'FROM policies',
'WHERE UPPER(TRIM(status)) = ''VIGENTE''',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Vencen en 30 d\00EDas'','),
'    TO_CHAR(COUNT(*), ''FM999G999G990''),',
'    ''fa fa-calendar'',',
'    3',
'FROM policies',
'WHERE expiration_date >= TRUNC(SYSDATE)',
'  AND expiration_date < TRUNC(SYSDATE) + 31',
'',
'UNION ALL',
'',
'SELECT',
'    ''Prima del Mes'',',
'    ''Gs. '' || TO_CHAR(',
'        NVL(SUM(premium_amount), 0),',
'        ''FM999G999G999G999G990''',
'    ),',
'    ''fa fa-money'',',
'    4',
'FROM policies',
'WHERE issue_date >= TRUNC(SYSDATE, ''MM'')',
'  AND issue_date < ADD_MONTHS(TRUNC(SYSDATE, ''MM''), 1)',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Comisi\00F3n del Mes'','),
'    ''Gs. '' || TO_CHAR(',
'        NVL(SUM(commission_own), 0)',
'        - NVL(SUM(commission_third_party), 0),',
'        ''FM999G999G999G999G990''',
'    ),',
'    ''fa fa-line-chart'',',
'    5',
'FROM policies',
'WHERE issue_date >= TRUNC(SYSDATE, ''MM'')',
'  AND issue_date < ADD_MONTHS(TRUNC(SYSDATE, ''MM''), 1)',
'',
'UNION ALL',
'',
'SELECT',
'    ''Meta Alcanzada'',',
'    TO_CHAR(',
'        ROUND(',
'            CASE',
'                WHEN NVL(SUM(t.target_premium), 0) = 0 THEN 0',
'                ELSE NVL(SUM(p.premium_real), 0)',
'                     / SUM(t.target_premium)',
'                     * 100',
'            END,',
'            2',
'        ),',
'        ''FM999G990D00''',
'    ) || ''%'',',
'    ''fa fa-bullseye'',',
'    6',
'FROM production_targets t',
'LEFT JOIN (',
'    SELECT',
'        product_type_id,',
'        insurer_id,',
'        EXTRACT(YEAR FROM issue_date) AS anio,',
'        EXTRACT(MONTH FROM issue_date) AS mes,',
'        SUM(NVL(premium_amount, 0)) AS premium_real',
'    FROM policies',
'    WHERE issue_date IS NOT NULL',
'    GROUP BY',
'        product_type_id,',
'        insurer_id,',
'        EXTRACT(YEAR FROM issue_date),',
'        EXTRACT(MONTH FROM issue_date)',
') p',
'    ON p.product_type_id = t.product_type_id',
'   AND p.insurer_id = t.insurer_id',
'   AND p.anio = t.target_year',
'   AND p.mes = t.target_month',
'WHERE t.target_year = EXTRACT(YEAR FROM SYSDATE)',
'  AND t.target_month = EXTRACT(MONTH FROM SYSDATE)',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
