,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
unistr('    ''Producci\00F3n'' AS nombre_serie,'),
'',
'    TO_CHAR(',
'        TRUNC(issue_date, ''MM''),',
'        ''Mon YYYY'',',
'        ''NLS_DATE_LANGUAGE=SPANISH''',
